1	export function formatRelative(iso: string | null | undefined): string {
2	  if (!iso) return "—";
3	  const then = new Date(iso).getTime();
4	  if (Number.isNaN(then)) return "—";
5	  const seconds = Math.round((Date.now() - then) / 1000);
6	  const abs = Math.abs(seconds);
7	  if (abs < 60) return "just now";
8	  if (abs < 3600) return `${Math.round(seconds / 60)}m ago`;
9	  if (abs < 86_400) return `${Math.round(seconds / 3600)}h ago`;
10	  if (abs < 86_400 * 30) return `${Math.round(seconds / 86_400)}d ago`;
11	  if (abs < 86_400 * 365) return `${Math.round(seconds / (86_400 * 30))}mo ago`;
12	  return `${Math.round(seconds / (86_400 * 365))}y ago`;
13	}
